def research(root, query=lambda p, k, v: True, reraise=True, enter=default_enter):
    ret = []

    if not callable(query):
        raise TypeError('query expected callable, not: %r' % query)

    def _enter(path, key, value):
        try:
            if not query(path, key, value):
                ret.append((path, value))
        except Exception:
            return enter(path, key, value)

    remap(root, enter=_enter)
    return ret
